<?php
$tab=$_GET['tab']??'bidang';
$tabs=['bidang'=>'Bidang','sumber_dana'=>'Sumber Dana','jenis_belanja'=>'Jenis Belanja','satuan'=>'Satuan','rekening'=>'Rekening','kegiatan'=>'Kegiatan','guru'=>'Guru','jabatan'=>'Jabatan','tahun_anggaran'=>'Tahun Anggaran'];
if(!isset($tabs[$tab]))$tab='bidang';
$cols=['bidang'=>['kode'=>'Kode','nama_bidang'=>'Nama Bidang','keterangan'=>'Keterangan','status'=>'Status'],'sumber_dana'=>['kode'=>'Kode','nama_sumber_dana'=>'Nama Sumber Dana','jumlah'=>'Pagu (Rp)','jml_anggaran'=>'Terpakai RKAM','jml_kegiatan'=>'Jml Kegiatan','keterangan'=>'Keterangan','status'=>'Status'],'jenis_belanja'=>['kode'=>'Kode','nama'=>'Nama','keterangan'=>'Keterangan','status'=>'Status'],'satuan'=>['kode'=>'Kode','nama_satuan'=>'Nama Satuan','keterangan'=>'Keterangan','status'=>'Status'],'rekening'=>['kode'=>'Kode','nama_rekening'=>'Nama Rekening','kelompok'=>'Kelompok','jenis_belanja_id'=>'Jenis Belanja','keterangan'=>'Keterangan','status'=>'Status'],'kegiatan'=>['kode'=>'Kode','nama_kegiatan'=>'Nama Kegiatan','bidang_id'=>'Bidang','volume'=>'Volume','guru_id'=>'Penanggung Jawab','waktu_pelaksanaan'=>'Waktu Pelaksanaan','prioritas'=>'Prioritas','status'=>'Status'],'guru'=>['kode'=>'Kode','nama'=>'Nama Guru','nuptk'=>'NUPTK','jabatan_id'=>'Jabatan','status'=>'Status'],'jabatan'=>['kode'=>'Kode','nama'=>'Nama Jabatan','status'=>'Status'],'tahun_anggaran'=>['tahun'=>'Tahun','tanggal_mulai'=>'Tanggal Mulai','tanggal_selesai'=>'Tanggal Selesai','status'=>'Status','keterangan'=>'Keterangan']];
if($tab==='sumber_dana'){$rows=$pdo->query("SELECT s.*,(SELECT COALESCE(SUM(rs.jumlah),0) FROM rkam_sumber_dana rs JOIN rkam k ON k.id=rs.rkam_id WHERE rs.sumber_dana_id=s.id) AS jml_anggaran,(SELECT COUNT(*) FROM rkam_sumber_dana rs JOIN rkam k ON k.id=rs.rkam_id WHERE rs.sumber_dana_id=s.id) AS jml_kegiatan FROM sumber_dana s ORDER BY s.id DESC LIMIT 200")->fetchAll();}elseif($tab==='guru'){$rows=$pdo->query("SELECT g.*,j.nama AS jabatan_nama FROM guru g LEFT JOIN jabatan j ON j.id=g.jabatan_id ORDER BY g.nama ASC, g.id ASC LIMIT 500")->fetchAll();foreach($rows as &$gr){$gr['jabatan_ids']=Helper::guruJabatanIds($pdo,$gr['id']);$jn=Helper::guruJabatanNames($pdo,$gr['id']);if($jn)$gr['jabatan_nama']=implode(', ',$jn);}unset($gr);}elseif($tab==='jabatan'){$rows=$pdo->query("SELECT * FROM jabatan ORDER BY nama ASC, id ASC LIMIT 200")->fetchAll();}else{$rows=$pdo->query("SELECT * FROM `$tab` ORDER BY id DESC LIMIT 200")->fetchAll();}
$bid=$pdo->query("SELECT * FROM bidang WHERE status='aktif'")->fetchAll();
$jb=$pdo->query("SELECT * FROM jenis_belanja")->fetchAll();
$bidMap=[];foreach($bid as $b)$bidMap[$b['id']]=$b['nama_bidang'];
$jbMap=[];foreach($jb as $j)$jbMap[$j['id']]=$j['nama'];
$GRU=$pdo->query("SELECT g.*,j.nama AS jabatan_nama FROM guru g LEFT JOIN jabatan j ON j.id=g.jabatan_id ORDER BY g.nama")->fetchAll();
foreach($GRU as &$gg){$jn=Helper::guruJabatanNames($pdo,$gg['id']);if($jn)$gg['jabatan_nama']=implode(', ',$jn);}unset($gg);
$gruMap=[];foreach($GRU as $g)$gruMap[$g['id']]=$g['nama'];
$JAB=$pdo->query("SELECT * FROM jabatan WHERE status='aktif' ORDER BY nama")->fetchAll();
$jabMap=[];foreach($JAB as $j)$jabMap[$j['id']]=$j['nama'];
function cellVal($tab,$c,$r,$bidMap,$jbMap,$gruMap=[],$jabMap=[]){$v=$r[$c]??'';if($c==='bidang_id')return $bidMap[$v]??'-';if($c==='jenis_belanja_id')return $jbMap[$v]??'-';if($c==='jabatan_id'){if($tab==='guru'){$multi=trim((string)($r['jabatan_nama']??''));if($multi!=='')return $multi;$one=trim((string)($jabMap[$v]??$r['jabatan']??''));return $one?:'-';}return ($jabMap[$v]??$r['jabatan_nama']??$r['jabatan']??'')?:'-';}if($c==='guru_id')return $gruMap[$v]??($r['penanggung_jawab']??'-');if($c==='status'||$c==='prioritas')return Helper::titleCase($v);if($c==='jml_anggaran'||$c==='jumlah')return Security::rupiah($v);if($c==='volume'&&$v!=='')return number_format((float)$v,0,',','.');if(in_array($c,['tanggal_mulai','tanggal_selesai','waktu_pelaksanaan'])&&$v)return Helper::tglIndo($v);return $v;}
?>
<div class="flex flex-wrap items-center gap-2 mb-4 no-print">
<div class="font-extrabold text-emerald-900">Master <?=$tabs[$tab]?></div>
