<span class="text-xs font-bold bg-emerald-100 text-emerald-800 border border-emerald-200 rounded-full px-3 py-1.5">Total: <?=$gTot?> | Aktif: <?=$gAkt?> | Nonaktif: <?=$gNon?></span>
<?php }?>
