<div class="bg-white rounded shadow px-3 py-2 mb-2 flex flex-wrap items-center gap-2 text-sm no-print">
<input type="checkbox" id="guruCheckAll" onchange="guruToggleAll(this)" class="w-4 h-4 accent-emerald-700" title="Pilih semua">
<span id="guruSelCount" class="text-xs font-bold text-emerald-900">0 dipilih</span>
<button onclick="guruBulkEditModal()" class="bg-amber-500 hover:bg-amber-600 text-white text-xs font-bold px-3 py-2 rounded-xl"><i class="fa-solid fa-pen-to-square mr-1"></i>Edit Massal</button>
<button onclick="guruBulkDelete()" class="bg-red-600 hover:bg-red-700 text-white text-xs font-bold px-3 py-2 rounded-xl"><i class="fa-solid fa-trash-can mr-1"></i>Hapus Massal</button>
<span class="text-[11px] text-gray-500 ml-auto">Urut A–Z by nama. Centang baris untuk aksi massal.</span>
</div>
<?php endif;?>
<div class="bg-white rounded shadow overflow-auto">
<?php if(!$rows):?><div class="p-10 text-center text-gray-500">Belum ada data.<br><button onclick="masterForm(0)" title="Tambah <?=$tabs[$tab]?>" class="mt-2 bg-emerald-700 hover:bg-emerald-800 text-white w-11 h-11 rounded-2xl shadow"><i class="fa-solid fa-plus"></i></button></div>
<?php else:?><table class="w-full text-sm"><thead><tr class="bg-gray-50 border-b"><?php if($tab==='guru'):?><th class="p-2 w-8 no-print"></th><?php endif;?><th class="p-2 w-10 text-left">No</th><?php foreach($cols[$tab] as $c=>$lbl):?><th class="p-2 text-left"><?=Security::e($lbl)?></th><?php endforeach;?><th class="p-2 no-print">Aksi</th></tr></thead>
<tbody><?php $no=1;foreach($rows as $r):?><tr class="border-b hover:bg-gray-50">
<?php if($tab==='guru'):?><td class="p-2 no-print"><input type="checkbox" class="guruCheck w-4 h-4 accent-emerald-700" value="<?=$r['id']?>" onchange="guruCountSel()"></td><?php endif;?>
<td class="p-2"><?=$no++?></td>
<?php foreach($cols[$tab] as $c=>$lbl):?><td class="p-2"><?=Security::e(cellVal($tab,$c,$r,$bidMap,$jbMap,$gruMap,$jabMap??[]))?></td><?php endforeach;?>
<td class="p-2 whitespace-nowrap no-print"><button onclick='masterForm(<?=$r['id']?>,<?=json_encode($r,JSON_HEX_APOS|JSON_HEX_QUOT)?>)' title="Edit" class="btn-ic btn-edit"><i class="fa-solid fa-pen-to-square"></i></button> <button onclick="masterDel(<?=$r['id']?>)" title="Hapus" class="btn-ic btn-del"><i class="fa-solid fa-trash-can"></i></button></td></tr><?php endforeach;?></tbody></table><?php endif;?></div>
<script>
const TAB='<?=$tab?>',BID=<?=json_encode($bid)?>,JB=<?=json_encode($jb)?>,SATL=<?=json_encode($pdo->query("SELECT * FROM satuan WHERE status='aktif' ORDER BY nama_satuan")->fetchAll())?>,GRU=<?=json_encode($GRU)?>,JAB=<?=json_encode($JAB)?>;
function fld(n,v,l,type,extra){return `<div class="mb-2"><label class="text-xs font-bold" style="text-transform:capitalize">${l}</label><input type="${type||'text'}" name="${n}" value="${(v??'').toString().replaceAll('"','')}" class="w-full border rounded p-2 mt-1" ${extra||''}></div>`;}
function selFld(n,v,l,opts){return `<div class="mb-2"><label class="text-xs font-bold" style="text-transform:capitalize">${l}</label><select name="${n}" class="w-full border rounded p-2 mt-1">${opts}</select></div>`;}
function masterForm(id,d){d=d||{};let h=`<div class="flex justify-between items-center mb-3"><b>${id?'Edit':'Tambah'} <?=$tabs[$tab]?></b><button type="button" onclick="closeModal()" title="Tutup" class="w-8 h-8 rounded-full bg-red-50 border border-red-200 text-red-600 hover:bg-red-100 flex items-center justify-center"><i class="fa-solid fa-xmark"></i></button></div><form onsubmit="masterSave(event,${id})">`;
const LBL={kode:'Kode',nama_bidang:'Nama Bidang',nama_sumber_dana:'Nama Sumber Dana',nama:'Nama',nama_satuan:'Nama Satuan',nama_rekening:'Nama Rekening',nama_kegiatan:'Nama Kegiatan',tahun:'Tahun',kelompok:'Kelompok',keterangan:'Keterangan',bidang_id:'Bidang',jenis_belanja_id:'Jenis Belanja',status:'Status',tanggal_mulai:'Tanggal Mulai',tanggal_selesai:'Tanggal Selesai',prioritas:'Prioritas',guru_id:'Penanggung Jawab (Guru)',nama_guru:'Nama Guru',nuptk:'NUPTK',jabatan_id:'Jabatan'};
const lb=k=>LBL[k]||k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const LBL2=Object.assign({},LBL,{jumlah:'Jumlah (Rp)'});
const lb2=k=>LBL2[k]||k.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const c={bidang:['nama_bidang'],sumber_dana:['nama_sumber_dana','jumlah'],jenis_belanja:['nama'],satuan:['nama_satuan'],rekening:['nama_rekening','kelompok'],kegiatan:['nama_kegiatan'],guru:['nama','nuptk'],jabatan:['nama'],tahun_anggaran:['tahun']}[TAB]||[];
c.forEach(k=>{if(k==='jumlah'){h+=`<div class="mb-2"><label class="text-xs font-bold" style="text-transform:capitalize">Jumlah (Rp)</label><input type="text" name="jumlah" data-money data-dec="0" value="${d.jumlah??0}" class="w-full border rounded p-2 mt-1" placeholder="0"></div>`;}else{h+=fld(k,d[k],lb2(k),k==='tahun'?'number':'text');}});
if(TAB==='guru'){const selIds=Array.isArray(d.jabatan_ids)?d.jabatan_ids.map(x=>String(x)):(d.jabatan_id?[String(d.jabatan_id)]:[]);h+=`<div class="mb-2"><label class="text-xs font-bold" style="text-transform:capitalize">Jabatan (bisa pilih lebih dari 1)</label><div class="flex gap-2 mt-1 mb-1"><button type="button" onclick="this.closest('form').querySelectorAll('input[name=&quot;jabatan_ids[]&quot;]').forEach(x=>x.checked=true)" class="text-[11px] font-bold text-emerald-700 underline">Pilih semua</button><button type="button" onclick="this.closest('form').querySelectorAll('input[name=&quot;jabatan_ids[]&quot;]').forEach(x=>x.checked=false)" class="text-[11px] font-bold text-gray-500 underline">Bersihkan</button></div><div class="border rounded p-2 max-h-44 overflow-y-auto grid gap-1 bg-white">${JAB.map(j=>`<label class="flex items-center gap-2 text-[13px] text-slate-700 hover:bg-emerald-50 rounded px-1 py-0.5 cursor-pointer"><input type="checkbox" name="jabatan_ids[]" value="${j.id}" ${selIds.includes(String(j.id))?'checked':''} class="w-4 h-4 accent-emerald-700 shrink-0">${j.nama}</label>`).join('')||'<span class="text-xs text-gray-400">Belum ada jabatan aktif.</span>'}</div></div>`;}
if(TAB==='kegiatan'){h+=selFld('bidang_id',d.bidang_id,'Bidang',`<option value="">- Pilih Bidang -</option>${BID.map(b=>`<option value="${b.id}" ${d.bidang_id==b.id?'selected':''}>${b.nama_bidang}</option>`).join('')}`)+fld('volume',Math.round(d.volume??1),'Volume','number','min="0" step="1" oninput="this.value=Math.max(0,Math.round(this.value||0))"')+selFld('satuan_id',d.satuan_id||'','Satuan',`<option value="">- Pilih Satuan -</option>${SATL.map(s=>`<option value="${s.id}" ${d.satuan_id==s.id?'selected':''}>${s.nama_satuan}</option>`).join('')}`)+fld('waktu_pelaksanaan',d.waktu_pelaksanaan,'Waktu Pelaksanaan','date')+selFld('guru_id',d.guru_id||'','Penanggung Jawab (Guru)',`<option value="">- Pilih Guru -</option>${GRU.map(g=>`<option value="${g.id}" ${(d.guru_id==g.id)?'selected':''}>${g.nama}${(g.jabatan_nama||g.jabatan)?' ('+(g.jabatan_nama||g.jabatan)+')':''}</option>`).join('')}`)+fld('sasaran',d.sasaran,'Sasaran');}
if(TAB==='rekening'){h+=selFld('jenis_belanja_id',d.jenis_belanja_id,'Jenis Belanja',`<option value="">-</option>${JB.map(b=>`<option value="${b.id}" ${d.jenis_belanja_id==b.id?'selected':''}>${b.nama}</option>`).join('')}`);}
if(['bidang','sumber_dana','jenis_belanja','satuan','rekening','kegiatan'].includes(TAB)){h+=fld('keterangan',d.keterangan,'Keterangan');}
if(TAB==='tahun_anggaran'){h+=fld('tanggal_mulai',d.tanggal_mulai,'Tanggal Mulai','date')+fld('tanggal_selesai',d.tanggal_selesai,'Tanggal Selesai','date')+fld('keterangan',d.keterangan,'Keterangan');}
if(['bidang','sumber_dana','jenis_belanja','satuan','rekening','kegiatan','guru','jabatan','tahun_anggaran'].includes(TAB)){const st=(d.status||'aktif').toLowerCase();const tc=s=>s.charAt(0).toUpperCase()+s.slice(1);const opt=v=>`<option value="${v}" ${st===v?'selected':''}>${tc(v)}</option>`;let so=opt('aktif')+opt('nonaktif');if(TAB==='tahun_anggaran')so+=opt('draft')+opt('selesai')+opt('dikunci');h+=selFld('status',st,'Status',so);}
if(TAB==='kegiatan'){h+=selFld('prioritas',d.prioritas||'sedang','Prioritas',['rendah','sedang','tinggi','mendesak'].map(p=>`<option value="${p}" ${d.prioritas===p?'selected':''}>${p.charAt(0).toUpperCase()+p.slice(1)}</option>`).join(''));}
h+=`<button class="w-full bg-emerald-700 text-white rounded p-2 font-bold">Simpan</button></form>`;openModal(h,'sm');}
async function masterSave(e,id){e.preventDefault();const f=e.target;const fd=new FormData(f);const d={act:'master_save',table:TAB,id};if(TAB==='guru'){d.jabatan_ids=JSON.stringify([...f.querySelectorAll('input[name="jabatan_ids[]"]:checked')].map(x=>x.value));fd.delete('jabatan_ids[]');}fd.forEach((v,k)=>{if(k==='jabatan_ids[]')return;d[k]=v;});const j=await api('x',d);if(j.ok){ok('Tersimpan');setTimeout(()=>location.reload(),800);}else err(j.msg||'Gagal');}
async function masterDel(id){if(!await ask('Hapus data ini?','Batal bila dipakai relasi lain.','Ya, Hapus'))return;const j=await api('x',{act:'master_delete',table:TAB,id});if(j.ok){ok('Dihapus');setTimeout(()=>location.reload(),800);}else err(j.msg||'Gagal');}
function guruSelIds(){return [...document.querySelectorAll('.guruCheck:checked')].map(x=>parseInt(x.value)).filter(x=>x>0);}
function guruCountSel(){const n=guruSelIds().length;const el=document.getElementById('guruSelCount');if(el)el.textContent=n+' dipilih';const all=document.getElementById('guruCheckAll');if(all){const tot=document.querySelectorAll('.guruCheck').length;all.checked=tot>0&&n===tot;all.indeterminate=n>0&&n<tot;}}
function guruToggleAll(cb){document.querySelectorAll('.guruCheck').forEach(x=>x.checked=cb.checked);guruCountSel();}
function guruBulkEditModal(){const ids=guruSelIds();if(!ids.length){err('Centang minimal 1 guru dulu');return;}let h=`<div class="flex justify-between items-center mb-3"><b>Edit Massal (${ids.length} Guru)</b><button type="button" onclick="closeModal()" title="Tutup" class="w-8 h-8 rounded-full bg-red-50 border border-red-200 text-red-600 flex items-center justify-center"><i class="fa-solid fa-xmark"></i></button></div><form onsubmit="guruBulkSave(event)"><div class="mb-2"><label class="text-xs font-bold">Jabatan Baru / Multiselect</label><div class="text-[11px] text-gray-500 mb-1">Mode: <select id="bulkJabMode" class="border rounded px-1 py-0.5 text-[11px] font-bold"><option value="skip">Tidak diubah</option><option value="set">Timpa jadi pilihan ini</option><option value="add">Tambah ke jabatan lama</option><option value="clear">Kosongkan jabatan</option></select></div><div class="border rounded p-2 max-h-44 overflow-y-auto grid gap-1 bg-white">${JAB.map(j=>`<label class="flex items-center gap-2 text-[13px] text-slate-700 hover:bg-emerald-50 rounded px-1 py-0.5 cursor-pointer"><input type="checkbox" name="jabatan_ids[]" value="${j.id}" class="w-4 h-4 accent-emerald-700 shrink-0">${j.nama}</label>`).join('')||'<span class="text-xs text-gray-400">Belum ada jabatan aktif.</span>'}</div></div><div class="mb-3"><label class="text-xs font-bold">Status Baru (kosongkan = tidak diubah)</label><select name="status" class="w-full border rounded p-2 mt-1"><option value="">- Tidak diubah -</option><option value="aktif">Aktif</option><option value="nonaktif">Nonaktif</option></select></div><button class="w-full bg-amber-500 text-white rounded p-2 font-bold">Update ${ids.length} Guru</button></form>`;openModal(h,'sm');}
async function guruBulkSave(e){e.preventDefault();const ids=guruSelIds();if(!ids.length){err('Centang minimal 1 guru dulu');return;}const f=e.target;const fd=new FormData(f);const mode=document.getElementById('bulkJabMode')?.value||'skip';const picks=[...f.querySelectorAll('input[name="jabatan_ids[]"]:checked')].map(x=>x.value);const j=await api('x',{act:'guru_bulk_update',ids:JSON.stringify(ids),jabatan_ids:mode==='skip'?'__skip__':JSON.stringify(picks),jabatan_mode:mode,status:fd.get('status')||''});if(j.ok){ok(j.msg);setTimeout(()=>location.reload(),900);}else err(j.msg||'Gagal');}
async function guruBulkDelete(){const ids=guruSelIds();if(!ids.length){err('Centang minimal 1 guru dulu');return;}if(!await ask(`Hapus ${ids.length} guru terpilih?`,'Guru dipakai RKAM/kegiatan batal dihapus.','Ya, Hapus'))return;const j=await api('x',{act:'guru_bulk_delete',ids:JSON.stringify(ids)});if(j.ok){ok(j.msg);setTimeout(()=>location.reload(),900);}else err(j.msg||'Gagal');}
function guruTemplateXlsx(){if(typeof XLSX==='undefined'){err('Library Excel belum termuat. Cek koneksi internet.');return;}const rows=[['Kode','Nama*','NUPTK','Jabatan','Status'],['','BUDI ASHARI','1234567890123456','Guru Kelas','aktif'],['','SITI AMINAH','','Guru Mapel','aktif']];const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=[{wch:12},{wch:26},{wch:20},{wch:18},{wch:10}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Guru');XLSX.writeFile(wb,'template_guru.xlsx');}
function guruImportModal(){let h=`<div class="flex justify-between items-center mb-3"><b>Impor Guru dari Excel</b><button type="button" onclick="closeModal()" title="Tutup" class="w-8 h-8 rounded-full bg-red-50 border border-red-200 text-red-600 hover:bg-red-100 flex items-center justify-center"><i class="fa-solid fa-xmark"></i></button></div>
<div class="text-sm space-y-3">
<div class="rounded-xl border border-emerald-100 bg-emerald-50/60 p-3 text-[13px]"><b>Langkah:</b> 1 Unduh template → 2 Isi Nama (wajib), NUPTK, Jabatan, Status → 3 Upload file .xlsx → 4 Impor. Baris tanpa Nama dilewati. Jabatan tak dikenal dibuat otomatis.</div>
<div class="flex flex-wrap gap-2"><button type="button" onclick="guruTemplateXlsx()" class="bg-emerald-700 hover:bg-emerald-800 text-white rounded-xl px-4 py-2 text-sm font-bold"><i class="fa-solid fa-download mr-1"></i> Unduh Template .xlsx</button></div>
<div><label class="text-xs font-bold">File Excel (.xlsx, max 5 MB)</label><input id="guruFile" type="file" accept=".xlsx" class="w-full border rounded-xl p-2 mt-1"></div>
<div id="guruPrev" class="hidden text-[13px]"></div>
<div id="guruProg" class="hidden"><div class="h-2.5 bg-emerald-100 rounded-full overflow-hidden"><div id="guruBar" class="h-2.5 rounded-full bg-emerald-600 transition-all" style="width:0%"></div></div><div id="guruTxt" class="mt-1 text-xs text-emerald-800 font-bold">0%</div></div>
<div class="flex gap-2"><button type="button" onclick="guruDoImport()" class="flex-1 bg-blue-600 hover:bg-blue-700 text-white rounded-xl p-2.5 font-bold"><i class="fa-solid fa-upload mr-1"></i> Impor Sekarang</button></div>
</div>`;openModal(h,'md');if(typeof XLSX==='undefined'){const s=document.createElement('script');s.src='https://cdn.sheetjs.com/xlsx-0.20.3/package/dist/xlsx.full.min.js';document.head.appendChild(s);}document.getElementById('guruFile').addEventListener('change',guruPreview);}
async function guruPreview(ev){const f=ev.target.files[0];const box=document.getElementById('guruPrev');if(!f||!box)return;if(!/\.xlsx$/i.test(f.name)){box.classList.remove('hidden');box.innerHTML='<div class="text-red-600 font-bold">File harus .xlsx sesuai template.</div>';return;}if(typeof XLSX==='undefined'){box.classList.remove('hidden');box.innerHTML='<div class="text-amber-700">Library Excel masih dimuat, coba lagi sebentar...</div>';return;}try{const buf=await f.arrayBuffer();const wb=XLSX.read(buf,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];const rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});const n=Math.max(0,rows.length-1);box.classList.remove('hidden');box.innerHTML='<div class="rounded-xl border border-blue-100 bg-blue-50/60 p-2.5">File: <b>'+f.name+'</b> • '+(f.size/1024).toFixed(1)+' KB • <b>'+n+'</b> baris data. Header: '+(rows[0]||[]).join(' | ')+'</div>';}catch(e){box.classList.remove('hidden');box.innerHTML='<div class="text-red-600">Gagal baca file: '+e.message+'</div>';}}
async function guruDoImport(){const inp=document.getElementById('guruFile');if(!inp||!inp.files.length){err('Pilih file .xlsx dulu');return;}const f=inp.files[0];if(!/\.xlsx$/i.test(f.name)){err('File harus .xlsx sesuai template');return;}if(f.size>5*1024*1024){err('File > 5 MB');return;}if(typeof XLSX==='undefined'){err('Library Excel belum termuat. Tunggu sebentar lalu coba lagi.');return;}
const prog=document.getElementById('guruProg'),bar=document.getElementById('guruBar'),txt=document.getElementById('guruTxt');prog.classList.remove('hidden');const paint=p=>{bar.style.width=p+'%';txt.innerText=p+'%';};paint(10);
let rows;try{const buf=await f.arrayBuffer();paint(35);const wb=XLSX.read(buf,{type:'array'});paint(55);const ws=wb.Sheets[wb.SheetNames[0]];rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:''});}catch(e){paint(0);prog.classList.add('hidden');err('Gagal baca Excel: '+e.message);return;}
paint(70);
const fd=new FormData();fd.append('csrf_token',window.__CSRF||CSRF);fd.append('act','guru_import');fd.append('rows',JSON.stringify(rows));
try{const r=await fetch((window.__BASE||BASE)+'api/x',{method:'POST',body:fd});paint(90);const j=await r.json();paint(100);
if(j.ok){Swal.fire({icon:'success',title:'Impor Selesai',html:'Berhasil: <b>'+j.inserted+'</b> • Dilewati: <b>'+j.skipped+'</b>'+(j.errors&&j.errors.length?'<div class="mt-2 text-left text-xs max-h-40 overflow-y-auto">'+j.errors.map(e=>'• '+e).join('<br>')+'</div>':''),confirmButtonText:'OK',confirmButtonColor:'#059669'}).then(()=>location.reload());}
else{Swal.fire({icon:'error',title:'Impor Gagal',html:(j.msg||'Gagal')+(j.errors&&j.errors.length?'<div class="mt-2 text-left text-xs max-h-40 overflow-y-auto">'+j.errors.map(e=>'• '+e).join('<br>')+'</div>':''),confirmButtonColor:'#dc2626'});}}catch(e){paint(0);err('Gagal: '+e.message);}}
async function syncGuruSimad(){
Swal.fire({title:'Menghubungi SIMAD...',text:'Mengambil data guru dari Endpoint SIMAD.',didOpen:()=>Swal.showLoading(),allowOutsideClick:false});
try{
const j=await api('x',{act:'sync_simad_guru'});
Swal.close();
if(j.ok){
Swal.fire({icon:'success',title:'Sinkronisasi Berhasil',html:`<b>${j.msg}</b><br><span class="text-xs text-gray-500">Waktu sinkron: ${j.sync_at}</span>`,confirmButtonColor:'#059669'}).then(()=>location.reload());
}else{
Swal.fire({icon:'error',title:'Sinkronisasi Gagal',text:j.msg||'Gagal sinkronisasi data dari SIMAD.',footer:'<a href="'+(window.__BASE||BASE)+'pengaturan?tab=endpoint" class="text-blue-600 underline text-xs font-bold">Atur URL Endpoint SIMAD di Pengaturan</a>'});
}
}catch(ex){Swal.close();err('Kesalahan koneksi sinkronisasi: '+ex.message);}
}
